"""Planner agent that turns a prompt into a structured :class:`AgentBuildPlan`."""

from __future__ import annotations

import dataclasses

try:
    from pydantic_ai import Agent
    from pydantic_ai.capabilities import AgentCapability, NativeTool, ProcessHistory
    from pydantic_ai.messages import (
        ModelMessage,
        ModelMessagesTypeAdapter,
        ModelRequest,
        ToolReturnPart,
    )
    from pydantic_ai.native_tools import WebSearchTool
    from pydantic_ai.settings import ModelSettings
except ImportError as exc:
    raise ImportError(
        "pydantic-ai-slim is required for Copilot v2. "
        "Install with: pip install rasa-pro[copilot-v2]"
    ) from exc

from rasa.builder.agent_plan.models import AgentBuildPlan
from rasa.builder.agent_plan.web_fetch import fetch_website_text
from rasa.builder.copilot.pydantic_ai.config import PydanticAIConfig

PLANNER_SYSTEM_PROMPT = """You are the Rasa Copilot planner for Mantle agents. From the user's description of an assistant, produce a build plan for a Mantle agent made of markdown skills.

A Mantle agent is: agent.yml (name, persona, rules), integrations.yml, and one folder per skill at skills/<skill_id>/skill.md — markdown with YAML frontmatter whose description is how the engine routes to the skill. Skills may declare memory entries and canned responses.

Constraints:
- Mantle only: no flows, slots, intents, entities, stories, rules, or forms.
- Keep the plan implementable: 2-6 skills, each with a snake_case id, a one-line routing description (make it discriminative — it is the routing surface), and a short step outline in plain imperative language.
- Note the memory entries each skill reads or writes, and any canned responses it needs.
- Give the agent a name and a 1-2 sentence persona summary.
- Record every assumption you made, and list open questions the user should answer.

If the user names a company, product, or domain but does not give a URL, use web search to find the official site, then call fetch_website on the best 1-2 results before producing the plan. If the user's prompt references a website URL directly, call fetch_website on it (and on at most 2-3 other obviously relevant URLs) without searching first. Ground skills, persona_summary, and assumptions in the actual content of the fetched page instead of guessing. Record in assumptions when the plan is grounded in a web search, a fetched page, or both. If neither search nor fetch turns up usable content, note that in open_questions instead of guessing at the site's content.

When refining an existing plan, change only what the feedback requires and keep everything else stable."""  # noqa: E501

FETCH_WEBSITE_TOOL_DESCRIPTION = (
    "Fetch a public web page the user referenced and return its readable text "
    "content, for grounding the plan in the site's actual content."
)

# Model-string prefixes pydantic-ai maps to OpenAI's Chat Completions API
# (`OpenAIChatModel`), as opposed to the Responses API (`OpenAIResponsesModel`,
# `openai-responses:` prefix). See `_resolve_planner_model_and_capabilities`.
_OPENAI_CHAT_MODEL_PREFIXES = ("openai-chat:", "openai:")
_OPENAI_RESPONSES_MODEL_PREFIX = "openai-responses:"

_FETCH_WEBSITE_TOOL_NAME = "fetch_website"
_COMPACTED_FETCH_RETURN_CHARS = 500
_FETCH_RETURN_COMPACTION_MARKER = (
    "\n\n[truncated: full page content was compacted from replayed history]"
)


# Module-level-lazy: constructing an Agent eagerly at import time would infer
# a model provider client (e.g. AsyncOpenAI) and fail on any process that
# imports this module without provider credentials configured — including
# test collection. Built on first use and cached here.
_planner_agent: Agent[None, AgentBuildPlan] | None = None


def get_planner_agent() -> Agent[None, AgentBuildPlan]:
    """Return the module-cached planner agent, building it on first call."""
    global _planner_agent
    if _planner_agent is None:
        config = PydanticAIConfig()
        model_name, web_search_capabilities = _resolve_planner_model_and_capabilities(
            config.model_name
        )
        _planner_agent = Agent(
            model_name,
            name="copilot_v2_planner",
            output_type=AgentBuildPlan,
            system_prompt=PLANNER_SYSTEM_PROMPT,
            model_settings=ModelSettings(timeout=config.stream_event_timeout),
            # `history_processors=` is a deprecated Agent kwarg in the installed
            # pydantic-ai (1.106); it's remapped internally onto this same
            # capability. Using it directly avoids the deprecation warning and
            # matches where the framework is headed.
            capabilities=[
                ProcessHistory(_compact_replayed_fetch_website_returns),
                *web_search_capabilities,
            ],
        )
        _register_web_fetch_tool(_planner_agent)
    return _planner_agent


def _resolve_planner_model_and_capabilities(
    model_name: str,
) -> tuple[str, list[AgentCapability[None]]]:
    """Point OpenAI models at the Responses API and enable built-in web search.

    pydantic-ai's ``WebSearchTool`` (OpenAI's server-side web search) is only
    accepted by ``OpenAIResponsesModel``; ``OpenAIChatModel`` raises a
    ``UserError`` if it's attached, since Chat Completions has no equivalent
    built-in tool (verified against the installed pydantic-ai's
    ``pydantic_ai/models/openai.py``). So when ``model_name`` targets OpenAI's
    Chat Completions API (the ``openai-chat:`` or bare ``openai:`` prefix),
    swap it to the equivalent ``openai-responses:`` model and return a
    ``WebSearchTool`` capability to attach alongside it. Any other model (a
    non-OpenAI provider such as Anthropic) is returned unchanged with no
    web-search capability, since ``WebSearchTool`` is OpenAI-specific.
    """
    for chat_prefix in _OPENAI_CHAT_MODEL_PREFIXES:
        if model_name.startswith(chat_prefix):
            responses_model_name = (
                _OPENAI_RESPONSES_MODEL_PREFIX + model_name[len(chat_prefix) :]
            )
            return responses_model_name, [NativeTool(WebSearchTool())]
    return model_name, []


def _register_web_fetch_tool(agent: Agent[None, AgentBuildPlan]) -> None:
    """Register the fetch_website tool that grounds plans in real page content."""

    @agent.tool_plain(name="fetch_website", description=FETCH_WEBSITE_TOOL_DESCRIPTION)
    async def fetch_website(url: str) -> str:
        """Fetch ``url`` and return its readable text content."""
        return await fetch_website_text(url)


def _compact_replayed_fetch_website_returns(
    messages: list[ModelMessage],
) -> list[ModelMessage]:
    """Truncate older ``fetch_website`` tool returns in replayed message history.

    The ``fetch_website`` tool can return up to ~20k chars of page text, and
    without compaction that content is replayed verbatim on every refine
    turn. This keeps the most recent ``fetch_website`` return intact (the
    model may still need the latest page content) and truncates any older
    ones to a short marker, leaving every other message part untouched.

    Registered as a ``ProcessHistory`` capability (the non-deprecated
    replacement for the ``history_processors=`` kwarg). Verified against the
    installed pydantic-ai (1.106) source: ``ProcessHistory.before_model_request``
    replaces ``request_context.messages``, and ``_agent_graph.py`` writes that
    processed list back into ``ctx.state.message_history`` (the same list
    object ``AgentRunResult.all_messages()`` returns) before the model call is
    made. So this compaction affects both what is sent to the model *and* what
    gets persisted via ``refine_plan``'s ``dump_json`` on the next round-trip.
    That's fine here: the compacted (truncated) history is what we want
    persisted too, since the full page dump is disposable once a newer fetch
    has happened.
    """
    fetch_return_positions = [
        (message_index, part_index)
        for message_index, message in enumerate(messages)
        if isinstance(message, ModelRequest)
        for part_index, part in enumerate(message.parts)
        if isinstance(part, ToolReturnPart)
        and part.tool_name == _FETCH_WEBSITE_TOOL_NAME
    ]
    if len(fetch_return_positions) <= 1:
        return messages

    older_positions = fetch_return_positions[:-1]
    compacted_messages = list(messages)
    for message_index, part_index in older_positions:
        request = compacted_messages[message_index]
        assert isinstance(
            request, ModelRequest
        )  # narrowed by fetch_return_positions above
        parts = list(request.parts)
        tool_return = parts[part_index]
        assert isinstance(tool_return, ToolReturnPart)
        if isinstance(tool_return.content, str) and len(tool_return.content) > (
            _COMPACTED_FETCH_RETURN_CHARS
        ):
            truncated_content = (
                tool_return.content[:_COMPACTED_FETCH_RETURN_CHARS]
                + _FETCH_RETURN_COMPACTION_MARKER
            )
            parts[part_index] = dataclasses.replace(
                tool_return, content=truncated_content
            )
            compacted_messages[message_index] = dataclasses.replace(
                request, parts=parts
            )

    return compacted_messages


async def create_plan(prompt: str) -> tuple[AgentBuildPlan, bytes]:
    """Run the planner on a fresh prompt and return the plan plus its messages.

    The returned bytes are the JSON-serialized ``all_messages()`` history,
    stored so a later refinement can resume the same pydantic-ai conversation.
    """
    result = await get_planner_agent().run(prompt)
    messages_json = ModelMessagesTypeAdapter.dump_json(result.all_messages())
    return result.output, messages_json


async def refine_plan(
    feedback: str, messages_json: bytes | None, current_plan: AgentBuildPlan
) -> tuple[AgentBuildPlan, bytes]:
    """Refine ``current_plan`` given user feedback.

    ``current_plan`` is always prepended to the prompt because a direct user
    edit (PATCH) never went through the model, so ``messages_json`` alone may
    be stale relative to what the user is actually looking at.
    """
    message_history = (
        ModelMessagesTypeAdapter.validate_json(messages_json) if messages_json else None
    )
    prompt = (
        f"Current plan (may include direct user edits):\n"
        f"{current_plan.model_dump_json()}\n\n"
        f"Feedback: {feedback}"
    )
    result = await get_planner_agent().run(prompt, message_history=message_history)
    messages_json_out = ModelMessagesTypeAdapter.dump_json(result.all_messages())
    return result.output, messages_json_out
